        match &self.generation { Some(v) => { row[1] = 0.0; row[1 + 1] = (*v); } None => { row[1] = 2.0; row[1 + 1..1 + 2].fill(0.0); } }
        row[3] = if self.alive { 1.0 } else { 0.0 };
