#[derive(Clone, Debug, Default, PartialEq)]
pub struct ClientMuzzles {
    pub barrels: Vec<u32>,
}

impl ClientMuzzles {
    pub const WORDS: usize = 2;
    pub const BARRELS: usize = 0;
    pub fn barrels_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[0] as usize; let length = row[1] as usize; heap[start..start + length * 1].chunks_exact(1) }

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 2] = (&mut row[..2]).try_into().unwrap();
        { let at = heap.len(); row[0] = at as f64; row[0 + 1] = self.barrels.len() as f64; heap.reserve(self.barrels.len() * 1); for e in self.barrels.iter() { let mut item = [0.0f64; 1]; { let row = &mut item; row[0] = (*e) as f64; } heap.extend_from_slice(&item); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 2] = (&row[..2]).try_into().unwrap();
        Self {
            barrels: { let (at, n) = (word_u32(row[0]) as usize, word_u32(row[0 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 1..at + (i + 1) * 1]; out.push(word_u32(row[0])); } out },
        }
    }

}

